     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.time.YearMonth;
    11	import java.time.format.DateTimeFormatter;
    12	import java.util.List;
    13	import java.util.Locale;
    14	
    15	public class ReportService {
    16	    private final ReservationRepository reservationRepository;
    17	    private final RoomRepository roomRepository;
    18	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    19	
    20	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    21	        this.reservationRepository = reservationRepository;
    22	        this.roomRepository = roomRepository;
    23	    }
    24	
    25	    public String generateOccupancyReport(LocalDate date) {
    26	        List<Reservation> reservations = reservationRepository.findPaidReservationsForNight(date);
    27	        List<Room> allRooms = roomRepository.findAll();
    28	
    29	        StringBuilder csv = new StringBuilder();
    30	        csv.append("room,type,reservation,check_in,check_out\n");
    31	
    32	        for (Reservation reservation : reservations) {
    33	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    34	            csv.append(reservation.getRoomNumber()).append(",");
    35	            csv.append(room.getType().name()).append(",");
    36	            csv.append(reservation.getId()).append(",");
    37	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    38	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
    39	        }
    40	
    41	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
    42	
    43	        return csv.toString();
    44	    }
    45	
    46	    public String generateRevenueReport(YearMonth month) {
    47	        List<Reservation> reservations = reservationRepository.findReservationsStartingInMonth(month);
    48	
    49	        StringBuilder csv = new StringBuilder();
    50	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    51	
    52	        BigDecimal totalRevenue = BigDecimal.ZERO;
    53	
    54	        for (Reservation reservation : reservations) {
    55	            BigDecimal revenue = calculateRevenue(reservation);
    56	
    57	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
    58	                csv.append(reservation.getId()).append(",");
    59	                csv.append(reservation.getRoomNumber()).append(",");
    60	                csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    61	                csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
    62	                csv.append(reservation.getStatus().name()).append(",");
    63	                csv.append(formatAmount(revenue)).append("\n");
    64	
    65	                totalRevenue = totalRevenue.add(revenue);
    66	            }
    67	        }
    68	
    69	        csv.append("total,").append(formatAmount(totalRevenue));
    70	
    71	        return csv.toString();
    72	    }
    73	
    74	    private BigDecimal calculateRevenue(Reservation reservation) {
    75	        BigDecimal revenue = reservation.getAmountPaid();
    76	
    77	        if (reservation.getRefund() != null) {
    78	            revenue = revenue.subtract(reservation.getRefund());
    79	        }
    80	
    81	        return revenue;
    82	    }
    83	
    84	    private String formatAmount(BigDecimal amount) {
    85	        return String.format(Locale.US, "%.2f", amount);
    86	    }
    87	}
