    24	
    25	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    26	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    27	                                        int guests, RatePlan ratePlan) {
    28	
    29	        Room room = roomService.getRoomByNumber(roomNumber);
    30	
    31	        if (guests < 1) {
    32	            throw new InvalidRequestException("At least one guest is required");
    33	        }
    34	
    35	        if (guests > room.getCapacity()) {
    36	            throw new CapacityExceededException("Room capacity exceeded");
    37	        }
    38	
    39	        if (!checkOut.isAfter(checkIn)) {
    40	            throw new InvalidRequestException("Check-out must be after check-in");
    41	        }
    42	
    43	        if (!reservationRepository.findConflictingReservations(roomNumber, checkIn, checkOut).isEmpty()) {
    44	            throw new RoomUnavailableException("Room is not available for the selected dates");
    45	        }
    46	
    47	        PricingCalculator.PricingResult pricing = PricingCalculator.calculate(room, checkIn, checkOut, ratePlan);
    48	
    49	        Reservation reservation = new Reservation();
    50	        reservation.setRoomNumber(roomNumber);
    51	        reservation.setGuestName(guestName);
    52	        reservation.setGuestEmail(guestEmail);
    53	        reservation.setGuestCpf(guestCpf);
    54	        reservation.setCheckIn(checkIn);
    55	        reservation.setCheckOut(checkOut);
    56	        reservation.setGuests(guests);
    57	        reservation.setRatePlan(ratePlan);
    58	        reservation.setNights(pricing.getNights());
    59	        reservation.setSubtotal(pricing.getSubtotal());
    60	        reservation.setDiscount(pricing.getDiscount());
    61	        reservation.setTotal(pricing.getTotal());
    62	        reservation.setStatus(ReservationStatus.PENDING);
    63	        reservation.setAmountPaid(BigDecimal.ZERO);
    64	        reservation.setRefund(null);
    65	
    66	        return reservationRepository.save(reservation);
    67	    }
    68	
    69	    public Reservation getReservation(Long id) {
    70	        return reservationRepository.findById(id)
    71	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
    72	    }
    73	
    74	    public Reservation confirmReservation(Long id) {
    75	        Reservation reservation = getReservation(id);
    76	
    77	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    78	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
    79	        }
    80	
    81	        reservation.setStatus(ReservationStatus.CONFIRMED);
    82	        reservation.setAmountPaid(reservation.getTotal());
    83	        reservationRepository.update(reservation);
    84	
    85	        sendConfirmationEmail(reservation);
    86	
    87	        return reservation;
    88	    }
    89	
    90	    public Reservation cancelReservation(Long id) {
    91	        Reservation reservation = getReservation(id);
    92	
    93	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
    94	            reservation.getStatus() == ReservationStatus.CHECKED_OUT) {
    95	            throw new OperationNotAllowedException("Cannot cancel after check-in");
    96	        }
    97	
    98	        if (reservation.getStatus() == ReservationStatus.CANCELLED) {
    99	            throw new OperationNotAllowedException("Reservation is already cancelled");
   100	        }
   101	
   102	        BigDecimal refundAmount = BigDecimal.ZERO;
   103	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   104	            refundAmount = reservation.getAmountPaid();
   105	        }
   106	
   107	        reservation.setStatus(ReservationStatus.CANCELLED);
   108	        reservation.setRefund(refundAmount);
   109	        reservationRepository.update(reservation);
   110	
   111	        return reservation;
   112	    }
   113	
   114	    public Reservation checkIn(Long id) {
   115	        Reservation reservation = getReservation(id);
   116	
   117	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   118	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
   119	        }
   120	
   121	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   122	        reservationRepository.update(reservation);
   123	
   124	        return reservation;
   125	    }
   126	
   127	    public Reservation checkOut(Long id) {
   128	        Reservation reservation = getReservation(id);
   129	
   130	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   131	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
   132	        }
   133	
   134	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   135	        reservationRepository.update(reservation);
   136	
   137	        return reservation;
   138	    }
   139	
   140	    public String getReceipt(Long id) {
   141	        Reservation reservation = getReservation(id);
   142	
   143	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   144	            throw new OperationNotAllowedException("Receipt is only available for paid reservations");
   145	        }
   146	
   147	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
   148	        return ReceiptFormatter.formatReceipt(reservation, room);
   149	    }
   150	
   151	    private void sendConfirmationEmail(Reservation reservation) {
   152	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
   153	        String receipt = ReceiptFormatter.formatReceipt(reservation, room);
   154	        String emailBody = ReceiptFormatter.formatConfirmationEmail(reservation.getGuestName(), receipt);
   155	
   156	        messagingService.sendEmail(
   157	            reservation.getGuestEmail(),
   158	            "Reserva confirmada - Pousada Maré Alta",
   159	            emailBody
   160	        );
   161	    }
