    24	
    25	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    26	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    27	                                        int guests, RatePlan ratePlan) {
    28	
    29	        Room room = roomService.getRoomByNumber(roomNumber);
    30	
    31	        if (guests < 1) {
    32	            throw new InvalidRequestException("At least one guest is required");
    33	        }
    34	
    35	        if (guests > room.getCapacity()) {
    36	            throw new CapacityExceededException("Room capacity exceeded");
    37	        }
    38	
    39	        if (!checkOut.isAfter(checkIn)) {
    40	            throw new InvalidRequestException("Check-out must be after check-in");
    41	        }
    42	
    43	        if (!reservationRepository.findConflictingReservations(roomNumber, checkIn, checkOut).isEmpty()) {
    44	            throw new RoomUnavailableException("Room is not available for the selected dates");
    45	        }
    46	
    47	        PricingCalculator.PricingResult pricing = PricingCalculator.calculate(room, checkIn, checkOut, ratePlan);
    48	
    49	        Reservation reservation = new Reservation();
    50	        reservation.setRoomNumber(roomNumber);
    51	        reservation.setGuestName(guestName);
    52	        reservation.setGuestEmail(guestEmail);
    53	        reservation.setGuestCpf(guestCpf);
    54	        reservation.setCheckIn(checkIn);
    55	        reservation.setCheckOut(checkOut);
    56	        reservation.setGuests(guests);
    57	        reservation.setRatePlan(ratePlan);
    58	        reservation.setNights(pricing.getNights());
    59	        reservation.setSubtotal(pricing.getSubtotal());
    60	        reservation.setDiscount(pricing.getDiscount());
    61	        reservation.setTotal(pricing.getTotal());
    62	        reservation.setStatus(ReservationStatus.PENDING);
    63	        reservation.setAmountPaid(BigDecimal.ZERO);
    64	        reservation.setRefund(null);
    65	
    66	        return reservationRepository.save(reservation);
    67	    }
