    74	    public Reservation confirmReservation(Long id) {
    75	        Reservation reservation = getReservation(id);
    76	
    77	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    78	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
    79	        }
    80	
    81	        reservation.setStatus(ReservationStatus.CONFIRMED);
    82	        reservation.setAmountPaid(reservation.getTotal());
    83	        reservationRepository.update(reservation);
    84	
    85	        sendConfirmationEmail(reservation);
    86	
    87	        return reservation;
    88	    }
