    90	    public Reservation cancelReservation(Long id) {
    91	        Reservation reservation = getReservation(id);
    92	
    93	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
    94	            reservation.getStatus() == ReservationStatus.CHECKED_OUT) {
    95	            throw new OperationNotAllowedException("Cannot cancel after check-in");
    96	        }
    97	
    98	        if (reservation.getStatus() == ReservationStatus.CANCELLED) {
    99	            throw new OperationNotAllowedException("Reservation is already cancelled");
   100	        }
   101	
   102	        BigDecimal refundAmount = BigDecimal.ZERO;
   103	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   104	            refundAmount = reservation.getAmountPaid();
   105	        }
   106	
   107	        reservation.setStatus(ReservationStatus.CANCELLED);
   108	        reservation.setRefund(refundAmount);
   109	        reservationRepository.update(reservation);
   110	
   111	        return reservation;
   112	    }
