   115	        Reservation reservation = getReservation(id);
   116	
   117	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   118	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
   119	        }
   120	
   121	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   122	        reservationRepository.update(reservation);
