   127	    public Reservation checkOut(Long id) {
   128	        Reservation reservation = getReservation(id);
   129	
   130	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   131	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
   132	        }
   133	
   134	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   135	        reservationRepository.update(reservation);
   136	
   137	        return reservation;
