   140	    public String getReceipt(Long id) {
   141	        Reservation reservation = getReservation(id);
   142	
   143	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   144	            throw new OperationNotAllowedException("Receipt is only available for paid reservations");
   145	        }
