   151	    private void sendConfirmationEmail(Reservation reservation) {
   152	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
   153	        String receipt = ReceiptFormatter.formatReceipt(reservation, room);
   154	        String emailBody = ReceiptFormatter.formatConfirmationEmail(reservation.getGuestName(), receipt);
