    15	
    16	    private boolean isValidEmail(String email) {
    17	        if (email == null || email.isEmpty()) {
    18	            return false;
    19	        }
    20	
    21	        int atIndex = email.indexOf('@');
    22	        if (atIndex <= 0 || atIndex != email.lastIndexOf('@')) {
    23	            return false;
    24	        }
    25	
    26	        String localPart = email.substring(0, atIndex);
    27	        String domain = email.substring(atIndex + 1);
    28	
    29	        if (localPart.isEmpty() || domain.isEmpty()) {
    30	            return false;
    31	        }
    32	
    33	        return domain.contains(".");
    34	    }
    35	}
