     1	package com.pousadamarealta.util;
     2	
     3	import com.pousadamarealta.model.RatePlan;
     4	import com.pousadamarealta.model.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.LocalDate;
     9	import java.time.Month;
    10	
    11	public class PricingCalculator {
    12	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    13	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    14	
    15	    public static class PricingResult {
    16	        private final int nights;
    17	        private final BigDecimal subtotal;
    18	        private final BigDecimal discount;
    19	        private final BigDecimal total;
    20	
    21	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    22	            this.nights = nights;
    23	            this.subtotal = subtotal;
    24	            this.discount = discount;
    25	            this.total = total;
    26	        }
    27	
    28	        public int getNights() {
    29	            return nights;
    30	        }
    31	
    32	        public BigDecimal getSubtotal() {
    33	            return subtotal;
    34	        }
    35	
    36	        public BigDecimal getDiscount() {
    37	            return discount;
    38	        }
    39	
    40	        public BigDecimal getTotal() {
    41	            return total;
    42	        }
    43	    }
    44	
    45	    public static PricingResult calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    46	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    47	
    48	        BigDecimal subtotal = BigDecimal.ZERO;
    49	        LocalDate currentDate = checkIn;
    50	
    51	        for (int i = 0; i < nights; i++) {
    52	            BigDecimal nightlyRate = room.getNightlyRate();
    53	
    54	            if (isHighSeason(currentDate)) {
    55	                nightlyRate = nightlyRate.multiply(HIGH_SEASON_MULTIPLIER);
    56	                nightlyRate = round(nightlyRate);
    57	            }
    58	
    59	            subtotal = subtotal.add(nightlyRate);
    60	            currentDate = currentDate.plusDays(1);
    61	        }
    62	
    63	        subtotal = round(subtotal);
    64	
    65	        BigDecimal discount = BigDecimal.ZERO;
    66	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    67	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT);
    68	            discount = round(discount);
    69	        }
    70	
    71	        BigDecimal total = subtotal.subtract(discount);
    72	        total = round(total);
    73	
    74	        return new PricingResult(nights, subtotal, discount, total);
    75	    }
    76	
    77	    private static boolean isHighSeason(LocalDate date) {
    78	        Month month = date.getMonth();
    79	        int day = date.getDayOfMonth();
    80	
    81	        if (month == Month.DECEMBER && day >= 15) {
    82	            return true;
    83	        }
    84	
    85	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    86	            return true;
    87	        }
    88	
    89	        if (month == Month.JULY) {
    90	            return true;
    91	        }
    92	
    93	        return false;
    94	    }
    95	
    96	    private static BigDecimal round(BigDecimal value) {
    97	        return value.setScale(2, RoundingMode.HALF_EVEN);
    98	    }
    99	}
